@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--acid:#d4fa65;--ink:#121713;--muted:#a3aa9f;--line:#ffffff24;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:'Manrope',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101510;color:white;font-family:var(--body);-webkit-tap-highlight-color:transparent;touch-action:none}.game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#667451}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,#10140e1c 75%,#0b100de0 145%),linear-gradient(180deg,#0b100d99 0%,transparent 23%,transparent 65%,#0b100ddb 100%)}.topbar{position:absolute;top:0;left:0;right:0;height:82px;padding:20px 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,#101510db,#10151000);z-index:2}.brand{display:flex;align-items:center;gap:11px}.brand-mark{display:grid;place-items:center;width:34px;height:38px;background:var(--acid);color:#15200f;font:900 25px var(--display);clip-path:polygon(0 0,100% 0,100% 74%,50% 100%,0 74%)}.brand div{display:grid;gap:1px}.brand b{font:800 16px var(--display);letter-spacing:1.9px}.brand small,.top-right small,.map-label,.mission-card small,.stat-line,.weapon-foot,.crosshair-hint,.start-note,.brief-stats small,.overline,.result-stats small{font:10px var(--mono);letter-spacing:1.1px;color:#b1b8ae}.match-status{display:flex;align-items:center;gap:9px;padding:8px 13px;border:1px solid #ffffff20;background:#11171384;font:10px var(--mono);letter-spacing:1.1px;color:#e3e7df}.live-dot{width:7px;height:7px;background:var(--acid);border-radius:50%;box-shadow:0 0 11px #d4fa6588;display:inline-block}.top-right{display:flex;align-items:center;gap:23px}.alive,.match-time{display:grid;grid-template-columns:auto auto;column-gap:7px;align-items:center}.alive i{grid-row:span 2;color:var(--acid);font-style:normal;font-size:19px}.alive b,.match-time b{font:600 19px var(--display)}.alive small,.match-time small{grid-column:2;font-size:8px}.match-time{border-left:1px solid var(--line);padding-left:17px}.compass{position:absolute;top:87px;left:50%;transform:translateX(-50%);display:flex;gap:14px;align-items:center;color:#e4e9dc;font:10px var(--mono);text-shadow:0 1px 5px #000}.compass b{font-weight:500;color:var(--acid)}.compass i{width:1px;height:6px;background:#ffffff75}.map-card{position:absolute;right:32px;top:106px;width:152px;padding:2px;background:#101611ba;border:1px solid #ffffff42;box-shadow:0 8px 28px #0004}.map-card canvas{width:148px;height:148px;display:block}.map-label{display:flex;justify-content:space-between;padding:8px 4px 5px;font-size:8px}.map-label b{color:var(--acid);font-weight:400}.mission-card{position:absolute;left:32px;top:116px;display:flex;gap:11px;align-items:center;padding:11px 15px 11px 11px;background:#111713ae;border-left:2px solid var(--acid);box-shadow:0 6px 22px #0002}.mission-icon{font-size:21px;color:var(--acid)}.mission-card div:last-child{display:grid;gap:3px}.mission-card small{font-size:8px}.mission-card b{font-size:11px;font-weight:600}.zone-warning{position:absolute;left:50%;top:145px;transform:translate(-50%,-12px);display:flex;gap:10px;align-items:center;padding:10px 15px;background:#451d17ed;border:1px solid #ff765e88;opacity:0;transition:.3s;pointer-events:none}.zone-warning.show{opacity:1;transform:translate(-50%,0)}.zone-warning>span{font-size:20px;color:#ff8c70}.zone-warning div{display:grid;gap:3px}.zone-warning b{font-size:10px;letter-spacing:1px}.zone-warning small{font:8px var(--mono);color:#ffc4b4}.bottom-hud{position:absolute;left:32px;right:32px;bottom:28px;display:flex;align-items:end;justify-content:space-between;pointer-events:none}.player-stats{width:220px;padding:13px 15px 12px;background:#111713d9;border:1px solid #ffffff26;box-shadow:0 7px 25px #0003}.stat-line{display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:.8px}.stat-line b{margin-left:auto;color:#fff;font:500 13px var(--mono)}.stat-meta{font-size:9px;color:#858d82}.stat-icon{color:#ff7767;font-size:14px}.stat-name{color:#c1c7bd}.bar{height:4px;margin:6px 0 9px;background:#ffffff1a;overflow:hidden}.bar i{display:block;width:100%;height:100%;background:#c9f46a;transition:width .2s}.health-bar i{background:linear-gradient(90deg,#c1ed59,#d4fa65)}.armor-line .stat-icon{color:#70bbff}.armor-line b{color:#9bcfff}.armor-bar{height:3px;margin-bottom:0}.armor-bar i{background:#70bbff}.weapon-card{width:220px;padding:11px 15px 10px;background:#111713e8;border:1px solid #ffffff35;box-shadow:0 7px 25px #0003}.weapon-type{display:flex;align-items:center;gap:7px;color:#e4e9df;font:10px var(--mono);letter-spacing:1px}.weapon-chip{padding:3px 5px;background:#d4fa65;color:#17200f;font-size:8px;font-weight:500}.mode-chip{margin-left:auto;color:#aab1a5;font-size:8px}.ammo-row{display:flex;align-items:baseline;gap:8px;margin:1px 0}.ammo-row>b{font:600 36px var(--display);letter-spacing:1px}.ammo-row>span{font:14px var(--mono);color:#8f988b}.ammo-row button{margin-left:auto;border:0;background:transparent;color:var(--acid);font-size:23px;cursor:pointer;pointer-events:auto}.weapon-foot{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.5px}.weapon-foot span:first-child{color:var(--acid)}.weapon-foot b{color:#fff}.weapon-foot .fire-hint{color:#939c90}.crosshair{position:absolute;top:50%;left:50%;width:18px;height:18px;transform:translate(-50%,-50%);transition:transform .15s;pointer-events:none;opacity:.8}.crosshair i{position:absolute;background:#fff;height:5px;width:1px;left:8px}.crosshair i:nth-child(1){top:0}.crosshair i:nth-child(2){bottom:0}.crosshair i:nth-child(3),.crosshair i:nth-child(4){width:5px;height:1px;top:8px}.crosshair i:nth-child(3){left:0}.crosshair i:nth-child(4){right:0}.crosshair b{position:absolute;width:2px;height:2px;border-radius:50%;background:var(--acid);left:8px;top:8px}.crosshair.aiming{transform:translate(-50%,-50%) scale(.68)}.crosshair.aiming i{background:var(--acid)}.toast{position:absolute;top:55%;left:50%;transform:translate(-50%,10px);padding:8px 13px;background:#101611e8;border:1px solid #d4fa6560;color:var(--acid);font:10px var(--mono);letter-spacing:1px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.hit-marker{position:absolute;top:50%;left:50%;color:#fff;font:26px var(--display);opacity:0;transform:translate(-50%,-50%);pointer-events:none}.hit-marker.show{opacity:1}.crosshair-hint{position:absolute;bottom:145px;left:50%;transform:translateX(-50%);font-size:8px;letter-spacing:.7px;white-space:nowrap;color:#c5ccc1}.crosshair-hint kbd{font:8px var(--mono);color:#fff;border:1px solid #ffffff52;padding:3px 5px;background:#1117139c}.crosshair-hint>span{color:var(--acid);padding:0 6px}.overlay{position:absolute;inset:0;display:grid;place-items:center;background:#090e0bc4;backdrop-filter:blur(5px);z-index:5;transition:opacity .4s}.overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(490px,calc(100% - 38px));padding:36px 39px 28px;background:linear-gradient(145deg,#1d261e,#111713);border:1px solid #d4fa6549;box-shadow:0 22px 80px #0008;position:relative}.overlay-card:before,.overlay-card:after{content:'';position:absolute;width:15px;height:15px;border-color:var(--acid);border-style:solid}.overlay-card:before{top:-1px;left:-1px;border-width:1px 0 0 1px}.overlay-card:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}.overline{display:flex;align-items:center;gap:8px;color:#c5f158;font-size:9px}.title-lockup{display:grid;margin:25px 0 14px;font:700 29px var(--display);letter-spacing:2px;color:#f1f3eb}.title-lockup strong{font:900 48px/.93 var(--display);letter-spacing:1px;color:var(--acid)}.overlay-card p{color:#b4bcb0;font-size:12px;line-height:1.7}.brief-stats,.result-stats{display:grid;grid-template-columns:repeat(3,1fr);margin:23px 0 20px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:12px 0}.brief-stats>div,.result-stats>div{display:grid;gap:7px;border-right:1px solid var(--line);padding-left:11px}.brief-stats>div:first-child,.result-stats>div:first-child{padding-left:0}.brief-stats>div:last-child,.result-stats>div:last-child{border:0}.brief-stats small,.result-stats small{font-size:7px;letter-spacing:.7px}.brief-stats b,.result-stats b{font:500 13px var(--mono);color:#f1f3eb}.start-button{width:100%;height:48px;display:flex;justify-content:space-between;align-items:center;padding:0 17px;border:0;background:var(--acid);color:#15200f;font:800 14px var(--display);letter-spacing:1.5px;cursor:pointer;transition:.15s}.start-button:hover{background:#e2ff8c;transform:translateY(-1px)}.start-button span{font:21px var(--body)}.start-note{text-align:center;margin-top:14px;font-size:7px;letter-spacing:.6px}.start-note i{color:var(--acid);font-style:normal;padding:0 4px}.result-card{text-align:center}.result-card .overline{justify-content:center}.result-card h1{font:900 62px/.9 var(--display);color:var(--acid);margin:22px 0 10px}.result-card p{margin:0}.result-stats{grid-template-columns:1fr 1fr;text-align:left}.hidden{display:none!important}.mobile-controls{display:none}.stick-zone{position:absolute;left:25px;bottom:30px;width:138px;height:138px;display:grid;place-items:center}.stick-ring{width:112px;height:112px;border-radius:50%;border:1px solid #ffffff54;background:#11171366;display:grid;place-items:center}.stick-ring:before{content:'';position:absolute;width:74px;height:74px;border-radius:50%;border:1px solid #ffffff20}.stick-ring>div{width:45px;height:45px;border-radius:50%;background:#d4fa65bd;border:2px solid #f1ffcb;box-shadow:0 0 18px #d4fa6533}.stick-zone>span{position:absolute;bottom:4px;font:8px var(--mono);letter-spacing:1px;color:#e5e9dd}.touch-action{position:absolute;display:grid;place-content:center;justify-items:center;border:1px solid #ffffff65;color:#fff;background:#141a16b8;border-radius:50%;font:24px var(--body);touch-action:none}.touch-action small{font:7px var(--mono);letter-spacing:.5px}.fire-touch{right:25px;bottom:30px;width:72px;height:72px;border-color:#d4fa65;background:#d4fa65df;color:#17200f;font-size:29px;box-shadow:0 0 20px #d4fa6530}.fire-touch small{color:#27351c}.ads-touch{right:106px;bottom:55px;width:50px;height:50px}.crouch-touch{right:115px;bottom:118px;width:43px;height:43px}.reload-touch{right:30px;bottom:118px;width:43px;height:43px}.heal-touch{right:168px;bottom:44px;width:48px;height:48px;color:var(--acid)}
