@media(max-height:520px){.topbar{height:56px;padding-top:8px;padding-bottom:8px}.compass{top:59px}.map-card{top:71px;width:94px}.map-card canvas{width:90px;height:90px}.mission-card{top:75px}.bottom-hud{bottom:12px}.crosshair-hint{bottom:98px}.mobile-controls .stick-zone{bottom:3px}.fire-touch{bottom:9px}.ads-touch{bottom:32px}.crouch-touch,.reload-touch{bottom:91px}.heal-touch{bottom:24px}}

