(() => {
  'use strict';
  const canvas = document.querySelector('#game'), ctx = canvas.getContext('2d', { alpha: false });
  const mapCanvas = document.querySelector('#minimap'), mapCtx = mapCanvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { alive:$('aliveCount'), clock:$('clock'), status:$('statusText'), health:$('healthNum'), healthFill:$('healthFill'), armor:$('armorNum'), armorFill:$('armorFill'), ammo:$('ammoNow'), reserve:$('ammoReserve'), meds:$('medCount'), medTouch:$('medTouchCount'), objective:$('objective'), warning:$('zoneWarning'), overlay:$('overlay'), start:$('startCard'), result:$('resultCard'), crosshair:$('crosshair'), hit:$('hitMarker'), toast:$('toast'), mode:$('modeText') };
  const WORLD = 2400, CENTER = WORLD/2, TAU = Math.PI*2;
  let W=0,H=0,dpr=1,scale=1,cam={x:CENTER,y:CENTER},playing=false,ended=false,elapsed=0,last=0,toastTimer=0,hitTimer=0,fireTimer=0,zoneDamageTimer=0,zoneWarningTimer=0,killCount=0,frame=0;
  let player, bots=[], loot=[], bullets=[], decor=[], keys={}, pointer={x:0,y:0,down:false}, move={x:0,y:0}, touchAim=null, crouching=false, ads=false;
  let zone={x:CENTER,y:CENTER,r:1000,startX:CENTER,startY:CENTER,startR:1000,endX:CENTER+110,endY:CENTER-80,endR:135,duration:210};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), rand=(a,b)=>a+Math.random()*(b-a), angleDiff=(a,b)=>Math.atan2(Math.sin(a-b),Math.cos(a-b));
  function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(W/900,H/650);scale=clamp(scale,.48,1.15);}
  addEventListener('resize',resize,{passive:true});resize();
  function newGame(){playing=true;ended=false;elapsed=0;killCount=0;fireTimer=zoneDamageTimer=zoneWarningTimer=0;bullets=[];zone={x:CENTER,y:CENTER,r:1000,startX:CENTER,startY:CENTER,startR:1000,endX:CENTER+110,endY:CENTER-80,endR:135,duration:210};player={x:CENTER+rand(-130,130),y:CENTER+rand(-130,130),r:15,angle:-Math.PI/2,hp:100,armor:35,ammo:30,reserve:90,meds:1,speed:210,alive:true};bots=[];for(let i=0;i<10;i++){let a=rand(0,TAU),r=rand(260,860);bots.push({x:CENTER+Math.cos(a)*r,y:CENTER+Math.sin(a)*r,r:14,hp:100,angle:rand(0,TAU),speed:rand(54,85),cool:rand(.8,2.4),wander:rand(0,TAU),wanderT:rand(.4,2),alive:true,flash:0});}spawnLoot();cam.x=player.x;cam.y=player.y;ui.overlay.classList.add('hidden');ui.start.classList.remove('hidden');ui.result.classList.add('hidden');ui.status.textContent='LIVE • SAFE ZONE ACTIVE';ui.objective.textContent='Be the last one standing';updateHud();last=performance.now();}
  function spawnLoot(){loot=[];const types=['ammo','medkit','armor','weapon'];for(let i=0;i<34;i++){let a=rand(0,TAU),r=rand(100,920),x=CENTER+Math.cos(a)*r,y=CENTER+Math.sin(a)*r;if(!blocked(x,y,20))loot.push({x,y,type:types[Math.floor(Math.random()*types.length)],alive:true});}}
  function blocked(x,y,pad=0){for(const o of decor)if(Math.hypot(x-o.x,y-o.y)<o.r+pad)return true;return false;}
  function generateMap(){decor=[];for(let i=0;i<150;i++){let x=rand(55,WORLD-55),y=rand(55,WORLD-55),r=rand(12,31);if(Math.hypot(x-CENTER,y-CENTER)<100)continue;decor.push({x,y,r,type:Math.random()<.65?'tree':'rock',tone:Math.random()});}for(let i=0;i<9;i++){let x=rand(220,WORLD-220),y=rand(220,WORLD-220),w=rand(60,130),h=rand(45,100);decor.push({x,y,r:Math.max(w,h)*.47,type:'building',w,h,tone:Math.random()});}}
  generateMap();
  function updateHud(){ui.health.textContent=Math.ceil(player.hp);ui.healthFill.style.width=clamp(player.hp,0,100)+'%';ui.armor.textContent=Math.ceil(player.armor);ui.armorFill.style.width=clamp(player.armor/100*100,0,100)+'%';ui.ammo.textContent=player.ammo;ui.reserve.textContent=player.reserve;ui.meds.textContent=player.meds;ui.medTouch.textContent=player.meds;ui.alive.textContent=(player.alive?1:0)+bots.filter(b=>b.alive).length;}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.5;}
  function damagePlayer(amount){let absorbed=Math.min(player.armor,amount*.65);player.armor-=absorbed;player.hp-=amount-absorbed;ui.health.textContent=Math.max(0,Math.ceil(player.hp));ui.healthFill.style.width=clamp(player.hp,0,100)+'%';ui.armor.textContent=Math.max(0,Math.ceil(player.armor));ui.armorFill.style.width=clamp(player.armor,0,100)+'%';if(player.hp<=0)finish(false);}
  function fire(){if(!playing||!player.alive)return;if(player.ammo<=0){if(player.reserve>0)reload();else toast('OUT OF AMMO');return;}if(fireTimer>0)return;player.ammo--;fireTimer=ads?.115:.17;const spread=ads?.018:(crouching?.035:.065),shot=player.angle+rand(-spread,spread),max=700;let target=null,targetD=max;for(const b of bots){if(!b.alive)continue;let dx=b.x-player.x,dy=b.y-player.y,d=Math.hypot(dx,dy),off=Math.abs(angleDiff(Math.atan2(dy,dx),shot));if(d<targetD&&off<Math.atan2(b.r+5,d)){target=b;targetD=d;}}if(target){target.hp-=ads?48:36;target.flash=.12;ui.hit.classList.add('show');hitTimer=.16;if(target.hp<=0){target.alive=false;killCount++;ui.objective.textContent=killCount+' operator'+(killCount===1?'':'s')+' eliminated';toast('OPERATOR ELIMINATED');updateHud();if(!bots.some(b=>b.alive))finish(true);}}bullets.push({x:player.x+Math.cos(shot)*24,y:player.y+Math.sin(shot)*24,a:shot,life:.09,player:true});updateHud();}
  function reload(){if(!playing||player.ammo>=30||player.reserve<=0)return;let n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;updateHud();toast('RELOADED');}
  function heal(){if(!playing||player.meds<=0||player.hp>=100){toast(player.meds<=0?'NO MEDKITS':'VITALS FULL');return;}player.meds--;player.hp=Math.min(100,player.hp+45);updateHud();toast('MEDKIT USED  +45 VITALS');}
  function finish(win){if(ended)return;ended=true;playing=false;ui.status.textContent=win?'EXTRACTION COMPLETE':'SIGNAL LOST';$('resultTitle').textContent=win?'VICTORY':'ELIMINATED';$('resultTitle').style.color=win?'#d4fa65':'#ff7767';$('resultCopy').textContent=win?'You were the last one standing.':'The island claimed another operator.';$('killsResult').textContent=killCount;$('timeResult').textContent=timeString(elapsed);ui.start.classList.add('hidden');ui.result.classList.remove('hidden');ui.overlay.classList.remove('hidden');}
  function timeString(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');}
  $('startBtn').addEventListener('click',newGame);$('playAgainBtn').addEventListener('click',newGame);$('reloadBtn').addEventListener('click',reload);$('mobileReload').addEventListener('click',reload);$('healBtn').addEventListener('click',heal);$('crouchBtn').addEventListener('pointerdown',e=>{e.preventDefault();crouching=true});$('crouchBtn').addEventListener('pointerup',()=>crouching=false);$('crouchBtn').addEventListener('pointercancel',()=>crouching=false);$('adsBtn').addEventListener('pointerdown',e=>{e.preventDefault();ads=true;ui.crosshair.classList.add('aiming')});$('adsBtn').addEventListener('pointerup',()=>{ads=false;ui.crosshair.classList.remove('aiming')});$('adsBtn').addEventListener('pointercancel',()=>{ads=false;ui.crosshair.classList.remove('aiming')});$('fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();pointer.down=true;fire()});$('fireBtn').addEventListener('pointerup',()=>pointer.down=false);$('fireBtn').addEventListener('pointercancel',()=>pointer.down=false);
  addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyC')crouching=true;if(e.code==='KeyR')reload();if(e.code==='KeyH')heal();if(e.code==='KeyQ'){ads=!ads;ui.crosshair.classList.toggle('aiming',ads);}});addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyC')crouching=false;});
  canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY;if(e.pointerType==='touch'&&e.clientX>W*.4&&playing){let rect=canvas.getBoundingClientRect(),wx=(e.clientX-W/2)/scale+cam.x,wy=(e.clientY-H/2)/scale+cam.y;player.angle=Math.atan2(wy-player.y,wx-player.x);}});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){pointer.down=true;fire();canvas.setPointerCapture(e.pointerId);}else if(e.clientX>W*.42){touchAim=e.pointerId;const wx=(e.clientX-W/2)/scale+cam.x,wy=(e.clientY-H/2)/scale+cam.y;player.angle=Math.atan2(wy-player.y,wx-player.x);}});canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')pointer.down=false;if(e.pointerId===touchAim)touchAim=null;});
  const stickZone=$('stickZone'),stickKnob=$('stickKnob');let stickId=null,stickOrigin=null;stickZone.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stickOrigin={x:e.clientX,y:e.clientY};stickZone.setPointerCapture(e.pointerId);});stickZone.addEventListener('pointermove',e=>{if(e.pointerId!==stickId)return;let dx=e.clientX-stickOrigin.x,dy=e.clientY-stickOrigin.y,l=Math.hypot(dx,dy),m=42;if(l>m){dx=dx/l*m;dy=dy/l*m;}move={x:dx/m,y:dy/m};stickKnob.style.transform=`translate(${dx}px,${dy}px)`;});function clearStick(){stickId=null;move={x:0,y:0};stickKnob.style.transform=''}stickZone.addEventListener('pointerup',clearStick);stickZone.addEventListener('pointercancel',clearStick);
  function movePlayer(dt){let x=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+move.x,y=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+move.y,l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}if(Math.hypot(x,y)>.08&&move.x===0&&move.y===0)player.angle=Math.atan2(y,x);let speed=player.speed*(crouching?.48:1)*(keys.ShiftLeft||keys.ShiftRight?1.32:1);let nx=clamp(player.x+x*speed*dt,24,WORLD-24),ny=clamp(player.y+y*speed*dt,24,WORLD-24);if(!blocked(nx,player.y,player.r))player.x=nx;if(!blocked(player.x,ny,player.r))player.y=ny;if(!move.x&&!move.y&&pointer.x&&pointer.y){const wx=(pointer.x-W/2)/scale+cam.x,wy=(pointer.y-H/2)/scale+cam.y;player.angle=Math.atan2(wy-player.y,wx-player.x);}cam.x+=(player.x-cam.x)*Math.min(1,dt*5);cam.y+=(player.y-cam.y)*Math.min(1,dt*5);}
  function updateZone(){let t=clamp(elapsed/zone.duration,0,1);t=t*t*(3-2*t);zone.x=zone.startX+(zone.endX-zone.startX)*t;zone.y=zone.startY+(zone.endY-zone.startY)*t;zone.r=zone.startR+(zone.endR-zone.startR)*t;let outside=dist(player,zone)>zone.r;if(outside){zoneDamageTimer+=1/60;if(zoneDamageTimer>=.6){zoneDamageTimer=0;damagePlayer(5);}}else zoneDamageTimer=0;const warning=outside||zone.r<440&&elapsed>30;ui.warning.classList.toggle('show',warning);}

