function updateZone(dt){let t=clamp(elapsed/zone.duration,0,1);t=t*t*(3-2*t);zone.x=zone.startX+(zone.endX-zone.startX)*t;zone.y=zone.startY+(zone.endY-zone.startY)*t;zone.r=zone.startR+(zone.endR-zone.startR)*t;let outside=dist(player,zone)>zone.r;if(outside){zoneDamageTimer+=dt;if(zoneDamageTimer>=.6){zoneDamageTimer=0;damagePlayer(5);}}else zoneDamageTimer=0;const warning=outside||zone.r<440&&elapsed>30;ui.warning.classList.toggle('show',warning);}
function updateBots(dt){for(const b of bots){if(!b.alive)continue;b.cool-=dt;b.wanderT-=dt;if(b.wanderT<=0){b.wander=rand(0,TAU);b.wanderT=rand(1,3);}const d=dist(b,player),inside=dist(b,zone)<zone.r;if(!inside){let a=Math.atan2(zone.y-b.y,zone.x-b.x);b.x+=Math.cos(a)*b.speed*1.35*dt;b.y+=Math.sin(a)*b.speed*1.35*dt;}else if(d<520){b.angle=Math.atan2(player.y-b.y,player.x-b.x);if(d>190){b.x+=Math.cos(b.angle)*b.speed*dt;b.y+=Math.sin(b.angle)*b.speed*dt;}else{b.x-=Math.cos(b.angle)*b.speed*.25*dt;b.y-=Math.sin(b.angle)*b.speed*.25*dt;}if(b.cool<=0){b.cool=rand(1.05,2.1);if(d<470&&Math.abs(angleDiff(b.angle,Math.atan2(player.y-b.y,player.x-b.x)))<.7&&Math.random()<.64){bullets.push({x:b.x,y:b.y,a:b.angle,life:.32,player:false});if(d<410)damagePlayer(rand(5,12));}}}else{b.x+=Math.cos(b.wander)*b.speed*.33*dt;b.y+=Math.sin(b.wander)*b.speed*.33*dt;}b.x=clamp(b.x,25,WORLD-25);b.y=clamp(b.y,25,WORLD-25);if(b.flash>0)b.flash-=dt;if(dist(b,zone)>zone.r){b.hp-=dt*7;if(b.hp<=0){b.alive=false;updateHud();}}} }
function updateLoot(){for(const item of loot){if(!item.alive||dist(player,item)>40)continue;item.alive=false;if(item.type==='ammo'){player.reserve+=30;toast('AMMO +30');}else if(item.type==='medkit'){player.meds++;toast('MEDKIT ACQUIRED');}else if(item.type==='armor'){player.armor=Math.min(100,player.armor+35);toast('ARMOR +35');}else{player.reserve+=45;player.ammo=Math.min(30,player.ammo+10);toast('RANGER AR • AMMO +45');}updateHud();}}
function updateBullets(dt){for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.life-=dt;if(b.life<=0){bullets.splice(i,1);continue;}if(!b.player&&dist(player,b)<22){bullets.splice(i,1);damagePlayer(rand(5,10));}}}
function drawWorld(){ctx.fillStyle='#74815a';ctx.fillRect(0,0,W,H);ctx.save();ctx.translate(W/2-cam.x*scale,H/2-cam.y*scale);ctx.scale(scale,scale);
  ctx.fillStyle='#89936b';ctx.fillRect(0,0,WORLD,WORLD);
  // Quiet terrain texture and field lanes.
  for(let i=0;i<95;i++){let x=(i*317+83)%WORLD,y=(i*719+169)%WORLD;ctx.fillStyle=i%3?'#a1a07412':'#d7c88a12';ctx.beginPath();ctx.ellipse(x,y,rand(14,48),rand(7,20),rand(-1,1),0,TAU);ctx.fill();}
  ctx.strokeStyle='#d5cc9b25';ctx.lineWidth=44;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(160,1700);ctx.bezierCurveTo(650,1500,830,1100,1200,1100);ctx.bezierCurveTo(1550,1050,1680,550,2200,440);ctx.stroke();ctx.strokeStyle='#f6e5ad29';ctx.lineWidth=2;ctx.stroke();
  // Safe zone fill, boundary, and storm outside.
  ctx.save();ctx.fillStyle='#e65a4a16';ctx.beginPath();ctx.rect(0,0,WORLD,WORLD);ctx.arc(zone.x,zone.y,zone.r,0,TAU,true);ctx.fill('evenodd');ctx.restore();ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,TAU);ctx.strokeStyle='#d9ff7c';ctx.lineWidth=3;ctx.setLineDash([12,8]);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r+7,0,TAU);ctx.strokeStyle='#d9ff7c33';ctx.lineWidth=1;ctx.stroke();
  // Buildings, rocks and trees.
  for(const o of decor){if(o.type==='building'){ctx.fillStyle='#374238';ctx.fillRect(o.x-o.w/2+5,o.y-o.h/2+7,o.w,o.h);ctx.fillStyle='#b8ac84';ctx.fillRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h);ctx.fillStyle=o.tone>.5?'#5e6a56':'#73725b';ctx.fillRect(o.x-o.w/2+5,o.y-o.h/2+5,o.w-10,o.h-10);ctx.fillStyle='#d0c293';ctx.fillRect(o.x-4,o.y-o.h/2+8,8,7);ctx.fillRect(o.x-4,o.y+o.h/2-15,8,7);}else if(o.type==='rock'){ctx.fillStyle='#606957';ctx.beginPath();ctx.ellipse(o.x+3,o.y+4,o.r*1.2,o.r*.8,-.25,0,TAU);ctx.fill();ctx.fillStyle='#aaa98a';ctx.beginPath();ctx.ellipse(o.x,o.y,o.r,o.r*.68,-.25,0,TAU);ctx.fill();}else{ctx.fillStyle='#334a35';ctx.beginPath();ctx.ellipse(o.x+3,o.y+9,o.r*.9,o.r*.55,0,0,TAU);ctx.fill();ctx.fillStyle=o.tone>.5?'#526d42':'#607748';ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,TAU);ctx.fill();ctx.fillStyle='#81905a';ctx.beginPath();ctx.arc(o.x-o.r*.26,o.y-o.r*.25,o.r*.47,0,TAU);ctx.fill();}}
  for(const item of loot){if(!item.alive)continue;const color={ammo:'#ebd770',medkit:'#ff7972',armor:'#7bc6ff',weapon:'#d4fa65'}[item.type];ctx.fillStyle='#111913aa';ctx.beginPath();ctx.ellipse(item.x,item.y+8,12,5,0,0,TAU);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(item.x-7,item.y-8,14,14,3);ctx.fill();ctx.fillStyle='#1c271b';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText({ammo:'⌁',medkit:'+',armor:'⬟',weapon:'↗'}[item.type],item.x,item.y-1);}
  for(const b of bots){if(!b.alive)continue;drawActor(b,false);}
  if(player.alive)drawActor(player,true);
  for(const b of bullets){ctx.strokeStyle=b.player?'#f8ffbd':'#ffb18b';ctx.lineWidth=b.player?3:2;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x+Math.cos(b.a)*27,b.y+Math.sin(b.a)*27);ctx.stroke();}
  ctx.restore();}
function drawActor(a,isPlayer){ctx.save();ctx.translate(a.x,a.y);ctx.rotate(a.angle);ctx.fillStyle='#10130f66';ctx.beginPath();ctx.ellipse(2,7,a.r*1.15,a.r*.75,0,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#d4fa65':(a.flash>0?'#fff':'#c36e55');ctx.beginPath();ctx.arc(0,0,a.r,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#354831':'#673d34';ctx.beginPath();ctx.arc(-2,-3,a.r*.55,0,TAU);ctx.fill();ctx.fillStyle='#25291f';ctx.fillRect(2,-3,a.r+12,6);ctx.fillStyle=isPlayer?'#f3ffd1':'#ffc1a8';ctx.beginPath();ctx.arc(6,0,3,0,TAU);ctx.fill();ctx.restore();if(!isPlayer&&a.hp<100){ctx.fillStyle='#142016';ctx.fillRect(a.x-14,a.y-a.r-9,28,3);ctx.fillStyle='#e5755d';ctx.fillRect(a.x-14,a.y-a.r-9,28*clamp(a.hp/100,0,1),3);}}

