const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});const page=await browser.newPage({viewport:{width:1024,height:720}});page.on('pageerror',e=>console.log('PAGEERROR',e.stack));page.on('console',m=>{if(m.type()==='error')console.log('CONSOLE',m.text())});page.on('requestfailed',r=>console.log('REQUESTFAILED',r.url(),r.failure()?.errorText));await page.goto('http://127.0.0.1:3002');await page.waitForTimeout(800);await page.locator('#startBtn').click();await page.waitForTimeout(2500);console.log('STATE',await page.evaluate(()=>({status:document.querySelector('#statusText').textContent,alive:document.querySelector('#aliveCount').textContent,clock:document.querySelector('#clock').textContent,health:document.querySelector('#healthNum').textContent,canvas:[document.querySelector('#game').width,document.querySelector('#game').height]})));await page.screenshot({path:'screenshots/last-light-match.jpg',type:'jpeg',quality:85});await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
